arguments.file_text:
namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string CourseNumber { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }

    public string FullCode => $"{DepartmentCode} {CourseNumber}";
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Pure and applied mathematics including statistics and analysis." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Literature, writing, and language studies." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "101", Title = "Introduction to Programming", Description = "Fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses. She holds a Ph.D. from MIT and has published extensively on CS education.", IsFeatured = true },
        new() { Id = 2, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques (sorting, searching, dynamic programming).", Credits = 4, Schedule = "TTh 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and competitive programming. He was a two-time ACM ICPC World Finalist.", IsFeatured = true },
        new() { Id = 3, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction processing, and introduction to NoSQL databases.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", InstructorName = "Dr. Maria Gonzalez", InstructorBio = "Dr. Gonzalez worked at Oracle for a decade before joining academia. Her research focuses on distributed database systems." },
        new() { Id = 4, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "450", Title = "Machine Learning", Description = "Supervised and unsupervised learning, neural networks, support vector machines, and practical applications using scikit-learn and TensorFlow.", Credits = 3, Schedule = "TTh 2:00–3:15 PM", InstructorName = "Dr. Alex Kumar", InstructorBio = "Dr. Kumar's research spans deep learning and natural language processing. He previously led ML teams at Google Brain.", IsFeatured = true },
        new() { Id = 5, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", InstructorName = "Dr. Robert Liu", InstructorBio = "Dr. Liu is an award-winning educator with a focus on making calculus accessible to all students." },
        new() { Id = 6, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science and engineering.", Credits = 3, Schedule = "TTh 9:00–10:15 AM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson researches abstract algebra and its computational applications. She has authored two widely-used textbooks.", IsFeatured = true },
        new() { Id = 7, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", InstructorName = "Dr. Robert Liu", InstructorBio = "Dr. Liu is an award-winning educator with a focus on making calculus accessible to all students." },
        new() { Id = 8, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based approach with weekly lab sessions.", Credits = 4, Schedule = "MWF 10:00–10:50 AM + Lab Thu 2:00–4:50 PM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is an experimental physicist specializing in condensed matter. He brings real-world lab experience into every lecture." },
        new() { Id = 9, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Prerequisite: PHYS 101.", Credits = 4, Schedule = "MWF 10:00–10:50 AM + Lab Tue 2:00–4:50 PM", InstructorName = "Dr. Lisa Nakamura", InstructorBio = "Dr. Nakamura's research focuses on quantum optics and photonics. She holds multiple patents in optical computing." },
        new() { Id = 10, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "110", Title = "College Composition", Description = "Develop clear, effective academic writing skills. Focus on argumentation, research methods, and revision strategies.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Prof. David Harper", InstructorBio = "Prof. Harper is a published novelist and essayist who has taught writing at the college level for over 20 years." },
        new() { Id = 11, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "250", Title = "American Literature", Description = "Survey of major American literary works from the colonial period to the present, including poetry, fiction, and drama.", Credits = 3, Schedule = "TTh 11:00–12:15 PM", InstructorName = "Dr. Angela Morrison", InstructorBio = "Dr. Morrison specializes in 20th-century American fiction and has published widely on Toni Morrison and James Baldwin." },
        new() { Id = 12, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "101", Title = "World Civilizations I", Description = "Survey of world history from ancient civilizations to 1500 CE. Covers Mesopotamia, Egypt, Greece, Rome, China, and the Islamic world.", Credits = 3, Schedule = "TTh 1:00–2:15 PM", InstructorName = "Dr. Patricia Owens", InstructorBio = "Dr. Owens is a historian of the ancient Mediterranean world with fieldwork experience at archaeological sites in Turkey and Greece.", IsFeatured = true },
        new() { Id = 13, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "210", Title = "Modern European History", Description = "Europe from the Enlightenment through the 20th century, covering revolutions, industrialization, world wars, and the EU.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", InstructorName = "Dr. Thomas Weber", InstructorBio = "Dr. Weber studied at Oxford and specializes in 20th-century German history. He is the author of three acclaimed monographs." },
    ];

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
