@page "/departments/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

@{
    var department = Catalog.GetDepartment(Id);
}

@if (department is null)
{
    <PageTitle>Department Not Found</PageTitle>
    <h1>Department Not Found</h1>
    <p>The requested department does not exist.</p>
    <a href="departments">← Back to departments</a>
}
else
{
    var courses = Catalog.GetCoursesByDepartment(Id);

    <PageTitle>@department.Name — University Course Catalog</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="departments">Departments</a></li>
            <li class="breadcrumb-item active">@department.Name</li>
        </ol>
    </nav>

    <h1>@department.Name (@department.Code)</h1>
    <p>@department.Description</p>

    <h3 class="mt-4">Courses</h3>

    @if (courses.Count == 0)
    {
        <p class="text-muted">No courses are currently offered in this department.</p>
    }
    else
    {
        <div class="list-group">
            @foreach (var course in courses)
            {
                <a href="courses/@course.Id" class="list-group-item list-group-item-action">
                    <div class="d-flex w-100 justify-content-between">
                        <h5 class="mb-1">@course.FullCode — @course.Title</h5>
                        <small>@course.Credits credits</small>
                    </div>
                    <p class="mb-1">@course.Schedule</p>
                    <small class="text-muted">@course.InstructorName</small>
                </a>
            }
        </div>
    }
}

@code {
    [Parameter]
    public int Id { get; set; }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>
<p>Submit a request to enroll in a course. All fields are required.</p>

@if (Submitted)
{
    var selectedCourse = Catalog.GetCourse(Model.CourseId);
    <div class="alert alert-success">
        <h4>Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
            <strong>@selectedCourse?.FullCode — @selectedCourse?.Title</strong> has been received.</p>
        <p>Your student ID: @Model.StudentId</p>
        <p>You will receive a confirmation via your university email within 2 business days.</p>
    </div>
    <a href="enroll" class="btn btn-outline-primary">Submit Another Request</a>
}
else
{
    <form method="post" class="row g-3" style="max-width: 600px;">
        <AntiforgeryToken />

        <div class="col-12">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" id="studentName" name="Model.StudentName" class="form-control"
                   value="@Model.StudentName" required />
        </div>

        <div class="col-12">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" class="form-control"
                   placeholder="e.g., STU-12345" value="@Model.StudentId" required />
        </div>

        <div class="col-12">
            <label for="courseId" class="form-label">Course</label>
            <select id="courseId" name="Model.CourseId" class="form-select" required>
                <option value="">— Select a course —</option>
                @foreach (var course in Catalog.GetAllCourses())
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
                        @course.FullCode — @course.Title (@course.Credits cr)
                    </option>
                }
            </select>
        </div>

        <div class="col-12">
            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            <a href="courses" class="btn btn-link">Cancel</a>
        </div>
    </form>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "course")]
    public int? PreselectedCourse { get; set; }

    public bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        if (PreselectedCourse.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = PreselectedCourse.Value;
        }
    }

    [CascadingParameter]
    public HttpContext? HttpContext { get; set; }

    protected override void OnParametersSet()
    {
        if (HttpContext?.Request.Method == "POST")
        {
            Submitted = !string.IsNullOrWhiteSpace(Model.StudentName)
                     && !string.IsNullOrWhiteSpace(Model.StudentId)
                     && Model.CourseId > 0;
        }
    }
}

